function buildDivBars(containerId, data) {
  const el = document.getElementById(containerId);
  const maxAbs = Math.max(...data.vals.map(Math.abs));
  let html = '';
  for (let i = 0; i < data.countries.length; i++) {
    const v = data.vals[i];
    const pct = Math.abs(v) / maxAbs * 48;
    const valClass = v > 0 ? 'pos' : v < 0 ? 'neg' : 'neu';
    const valTxt = v > 0 ? `+${v.toFixed(1)}%` : `${v.toFixed(1)}%`;

    const negBar = v < 0 ? `<div class="div-bar neg-bar" style="width:${pct}%"></div>` : '';
    const posBar = v > 0 ? `<div class="div-bar pos-bar" style="width:${pct}%"></div>` : '';

    html += `
      <div class="div-row">
        <div class="div-country">${data.countries[i]}</div>
        <div class="div-bar-center">
          <div class="div-center-line"></div>
          ${negBar}${posBar}
        </div>
        <div class="div-val ${valClass}">${valTxt}</div>
      </div>`;
  }
  el.innerHTML = html;
}

buildDivBars('div-apple', divData.apple);
